//! Per-glyph source-aware drawing comparison in one source mask/frame.
use kni_core::{capture::capture_gray,capture_dispatch::decode_source,jpeg_source::Limits,cubic_fit::FitPolicy,generated_draw::fit_from_source,reference_slice::{ReferenceRing,Span},lever_api::{count_nodes,missing_extrema}};
fn outline(rings:&[ReferenceRing])->String{let mut s=String::from("ring\tkind\tx1\ty1\tx2\ty2\tx\ty\n");for(i,r)in rings.iter().enumerate(){s+=&format!("{i}\tM\t\t\t\t\t{}\t{}\n",r.start.x,r.start.y);for p in &r.spans{match p{Span::Line{end}=>s+=&format!("{i}\tL\t\t\t\t\t{}\t{}\n",end.x,end.y),Span::Cubic{control_one:a,control_two:b,end}=>s+=&format!("{i}\tC\t{}\t{}\t{}\t{}\t{}\t{}\n",a.x,a.y,b.x,b.y,end.x,end.y)}}}s}
fn main()->Result<(),String>{let a:Vec<_>=std::env::args().collect();if a.len()!=10{return Err("usage: generated_draw_compare INPUT OUTPUT_DIR SCALE EPS SE REFITS MAX_BYTES MAX_PIXELS MAX_WORKING_BYTES".into())}let num=|i:usize|a[i].parse::<f64>().map_err(|_|"invalid numeric policy".to_string());let scale=num(3)?;let eps=num(4)?;let se=num(5)?;let refits=a[6].parse().map_err(|_|"invalid refits")?;if !eps.is_finite()||eps<0.0{return Err("invalid capture tolerance".into())}let n=|i:usize|a[i].parse::<usize>().map_err(|_|"invalid resource policy".to_string());let bytes=std::fs::read(&a[1]).map_err(|e|e.to_string())?;let d=decode_source(&bytes,&kni_core::capture::DecodeLimits{max_input_bytes:n(7)?,max_pixels:n(8)?,max_working_bytes:n(9)?},Limits{max_input_bytes:n(7)?,max_pixels:n(8)?,max_working_bytes:n(9)?}).map_err(|e|format!("{e:?}"))?;let cap=capture_gray(d.width,d.height,&d.gray,eps)?;let g=fit_from_source(&cap,&d.gray,scale,&FitPolicy{squared_error:se,max_refits:refits})?;let out=std::path::Path::new(&a[2]);std::fs::create_dir(out).map_err(|e|e.to_string())?;let report=format!("source_sha256={}\nsource_receipt={:?}\nscale={} capture_origin=({}, {})\nbaseline_area={} refined_area={}\nbaseline_nodes={} refined_nodes={}\nbaseline_missing_extrema={} refined_missing_extrema={}\nreports={:?}\nrefused={:?}\nIoU=NOT_MEASURED\n",kni_core::economy_eval::sha256_hex(&bytes),d.receipt,scale,cap.origin_x,cap.origin_y,g.baseline_area,g.final_area,count_nodes(&g.baseline),count_nodes(&g.rings),missing_extrema(&g.baseline),missing_extrema(&g.rings),g.reports,g.refused);for(name,body)in[("baseline.tsv",outline(&g.baseline)),("refined.tsv",outline(&g.rings)),("receipt.txt",report)]{std::fs::write(out.join(name),body).map_err(|e|e.to_string())?;}Ok(())}
